delay = cda.filter(pl.col("ever_paid") & (pl.col("DATA_INSCRICAO") >= pl.date(YEARS[0], 1, 1))) \
    .with_columns(pl.col("years_to_first_payment").floor().cast(pl.Int32).clip(0, 10).alias("delay")).group_by("delay").len().sort("delay")
